arguments.command:
cd /app/dclm && python3 - <<'EOF' > /tmp/scan.txt 2>&1
import re, os, subprocess
pats = {
 'akia': re.compile(r'(?:AKIA|ASIA)[0-9A-Z]{8,}'),
 'aws_secret_assign': re.compile(r'(?i)(aws_)?secret_access_key\s*[=:]\s*["\']?([A-Za-z0-9/+=]{20,})'),
 'aws_id_assign': re.compile(r'(?i)access_key_id\s*[=:]\s*["\']?([A-Za-z0-9/+=]{16,})'),
 'hf': re.compile(r'hf_[A-Za-z0-9]{15,}'),
 'gh': re.compile(r'(?:ghp|gho|ghu|ghs|ghr|github_pat)_[A-Za-z0-9_]{15,}'),
 'b64ish': re.compile(r'\b[A-Za-z0-9+/]{40}\b'),
}
hits=[]
files = subprocess.check_output(['git','ls-files']).decode().split()
for f in files:
    try: t=open(f, encoding='utf-8', errors='ignore').read()
    except Exception: continue
    for i,line in enumerate(t.splitlines(),1):
        for n,p in pats.items():
            if p.search(line):
                hits.append((f,i,n,line.strip()[:200]))
for h in hits: print(h)
print('total', len(hits))
EOF
wc -l /tmp/scan.txt; grep -c b64ish /tmp/scan.txt; grep -v b64ish /tmp/scan.txt | head -40

